#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn example() {
        let mut c = LruCache::new(2);
        c.put(1, 10);
        c.put(2, 20);
        assert_eq!(c.get(1), Some(10));
        c.put(3, 30);
        assert_eq!(c.get(2), None);
        assert_eq!(c.get(3), Some(30));
    }

    #[test]
    fn missing_key() {
        let mut c = LruCache::new(1);
        assert_eq!(c.get(99), None);
    }

    #[test]
    fn overwrite_refreshes() {
        let mut c = LruCache::new(2);
        c.put(1, 1);
        c.put(2, 2);
        c.put(1, 100);
        c.put(3, 3);
        assert_eq!(c.get(1), Some(100));
        assert_eq!(c.get(2), None);
    }

    #[test]
    fn capacity_one() {
        let mut c = LruCache::new(1);
        c.put(1, 1);
        c.put(2, 2);
        assert_eq!(c.get(1), None);
        assert_eq!(c.get(2), Some(2));
    }

    #[test]
    fn many_ops_fast() {
        let mut c = LruCache::new(1000);
        for i in 0..50000 {
            c.put(i, i * 2);
            c.get(i - 500);
        }
        assert_eq!(c.get(49999), Some(99998));
        assert_eq!(c.get(10), None);
    }
}
